from pathlib import Path
import base64

path = Path("worker.js")
source = path.read_text(encoding="utf-8")
old = base64.b64decode('').decode("utf-8")
new = base64.b64decode('').decode("utf-8")

if new in source:
    raise SystemExit(0)
if old not in source:
    raise SystemExit("phone normalization anchor not found")

path.write_text(source.replace(old, new, 1), encoding="utf-8", newline="\n")
